import weakref

class ImageCache:
    def __init__(self):
        self._images = weakref.WeakValueDictionary()   # name -> Image

    def get(self, name, load):
        img = self._images.get(name)
        if img is None:                                # dead or never loaded
            img = load(name)
            self._images[name] = img
        return img
